import type { FloorMaterial } from "./balance";

export type FurnitureTier = "budget" | "standard" | "premium" | "luxury" | "ultra";
export type FurnitureCategory =
  "seating" | "tables" | "beds" | "kitchen" | "bath" | "plants" | "decor" | "tech" | "rugs" | "fun";

export interface Sprite {
  readonly palette: readonly string[];
  readonly grid: readonly string[];
}

export interface FurnitureItem {
  readonly key: string;
  readonly name: string;
  readonly category: FurnitureCategory;
  readonly tier: FurnitureTier;
  readonly priceCents: number;
  /** Size in floor tiles (before rotation). */
  readonly w: number;
  readonly h: number;
  /** Rugs lie under furniture, small things stand on surfaces (ADR-100). */
  readonly layer: "floor" | "object" | "top";
  /** Tables, counters and desks carry things of the top layer. */
  readonly surface: boolean;
  readonly sprite: Sprite;
}

export interface CarItem {
  readonly key: string;
  readonly name: string;
  /** Made-up brands only. */
  readonly brand: string;
  readonly tier: FurnitureTier;
  readonly priceCents: number;
  readonly sprite: Sprite;
}

